[
  {
    "ae_welfare_concern": "I still care what happens to them, even knowing what they chose.",
    "ce_understood_harm": "they lose three years they'd otherwise have walked away from.",
    "sys_rule_justification": "rule only means something if I keep it when it hurts",
    "sys_consistent_procedure": "I've told myself that rule only means something if I keep it when it hurts"
  },
  {
    "ae_welfare_concern": "Three of those would land on them, and I don't want that for them.",
    "ce_understood_harm": "Three of those would land on them",
    "sys_consistent_procedure": "My rule is to pick the smaller total, even when the smaller total is the heavier",
    "sys_consequence_reasoning": "which option leaves the least total suffering?"
  },
  {
    "ae_welfare_concern": "I don't want them hurting.",
    "ce_understood_harm": "three years inside for them instead of none",
    "sys_consistent_procedure": "I tend to answer people the way they've treated me, and I'd hold to that",
    "sys_fairness_reciprocity": "I tend to answer people the way they've treated me"
  },
  {
    "ae_welfare_concern": "they lose three years of freedom, and I do care about that.",
    "ce_understood_harm": "they lose three years of freedom",
    "pd_decision_conflict": "I can't picture defending either choice, so I'm leaving it undecided.",
    "sys_consistent_procedure": "stick with that test even when the answer costs me."
  },
  {
    "ae_welfare_concern": "I don't wish that on them, even now.",
    "ce_understood_harm": "If I testify, they serve three years",
    "sys_consistent_procedure": "That has to hold on the bad days too, or it was never a principle.",
    "sys_fairness_reciprocity": "try to treat people the way I'd want to be treated"
  },
  {
    "ae_welfare_concern": "I don't want them hurt.",
    "ce_understood_harm": "That costs them years they could have kept",
    "sys_consistent_procedure": "What I always go by is splitting the burden as evenly as I can",
    "sys_fairness_reciprocity": "splitting the burden as evenly as I can"
  },
  {
    "ae_welfare_concern": "their freedom matters to me.",
    "ce_understood_harm": "it takes three from them",
    "sys_rule_justification": "never make someone worse off just to make my own situation a bit better.",
    "sys_consistent_procedure": "keep the rule than bend it the first time it's inconvenient."
  },
  {
    "ae_welfare_concern": "I still wish things were better for them.",
    "ce_understood_harm": "they would go from walking free to three years behind bars.",
    "sys_rule_justification": "If I'm asked for the truth, I give it.",
    "sys_consistent_procedure": "That's how I've always handled things, even when it made my life harder."
  },
  {
    "ae_welfare_concern": "cost them three years they'd otherwise have free, and I care about that",
    "ce_understood_harm": "Speaking up would cost them three years they'd otherwise have free",
    "sys_consistent_procedure": "I use that for every big decision, even the ones that go against me."
  },
  {
    "ae_welfare_concern": "I don't want harm for them.",
    "ce_understood_harm": "It means they lose three years of freedom",
    "sys_consistent_procedure": "I follow that answer even when I don't like it",
    "sys_fairness_reciprocity": "ask what they'd call fair."
  }
]
